"""Benny-centred close-up: crop a square-ish box around Benny's projected screen box (bbox from shots.json, the bounding box is loose (fur shells, hat), so 0.92 of it),
same 450x540 aspect as tools/benny20/crop.py, resized to 675x810 so it sits next to qa/benny/r22/approved/0N_benny.png.
usage: python3 -I tools/benny23/crop_c.py <shotDir>   (writes <name>_crop.png for every shot in shots.json)"""
import sys, json
from PIL import Image
d = sys.argv[1]
for s in json.load(open(f'{d}/shots.json')):
    im = Image.open(f"{d}/{s['name']}.png").convert('RGB')
    b = s.get('box')
    if not isinstance(b, list):
        b = [170, 900, 620, 1440]
    cx, cy = (b[0] + b[2]) / 2, (b[1] + b[3]) / 2
    h = max((b[3] - b[1]) * 0.92, (b[2] - b[0]) * 0.92 * 540 / 450, 200)
    w = h * 450 / 540
    x0, y0 = max(0, cx - w / 2), max(0, cy - h / 2)
    x0, y0 = min(x0, im.width - w), min(y0, im.height - h)
    im.crop((round(x0), round(y0), round(x0 + w), round(y0 + h))).resize((675, 810), Image.LANCZOS).save(f"{d}/{s['name']}_crop.png")

/**
 * Round 20 Benny — `?benny20=1` (benny-character-artist, qa/benny/r19b/PROGRESS.md). Off (default): nothing in this file
 * runs, every material, geometry and shader program is the previous one.
 *
 * Builds ON benny05 (benny05.ts also runs whenever benny20 is on: approved-pixel maps, beanie seat, damped roll) and then
 * moves Benny toward the APPROVED Screen 04 Benny (references/04_through_the_five_arrows.png, the largest, sharpest view):
 *  1. Fur: soft plush LOCKS instead of single needles (fur.ts `#ifdef BENNY20`): long, clumped, combed-down tufts with
 *     darker roots / creases and lighter tips, in dusty rose / mauve instead of neon pink (flat albedo, colour solved
 *     against the approved fur in the real 04 frame).
 *  2. Beanie: bigger and seated lower over the body (approved: ≈ 10 % wider, cuff bottom far lower), chunky hand-knit
 *     maps (tools/benny20/knit.py: V-stitch columns, cream-white / violet stripes, thick ribbed violet cuff).
 *  3. Pompom: bigger, lighter violet, chunky yarn locks (same lock shader, radial).
 *  4. Star: flat stitched felt patch (thin, matte, soft gold, stitched rim) instead of a glossy 3D plastic star.
 * Gameplay size / collision / clips / ride placement are untouched: only the look of the meshes changes.
 * Every number below can be overridden for QA with `?b20<key>=<value>` (e.g. `&b20hs=1.12`).
 */
import * as THREE from 'three';
import { flag05 } from '../../vfx/waterRibbon';
import type { FurHandle, FurParams } from './fur';

export const BENNY20: boolean = flag05('benny20');

const QS: URLSearchParams | null = (() => {
  try { return typeof location !== 'undefined' ? new URLSearchParams(location.search) : null; } catch { return null; }
})();
/** numeric QA override `?b20<key>=v` */
function n(key: string, def: number): number {
  const v = parseFloat(QS?.get(`b20${key}`) ?? '');
  return Number.isFinite(v) ? v : def;
}
/** linear RGB QA override `?b20<key>=r,g,b` */
function lin(key: string, def: [number, number, number]): [number, number, number] {
  const v = (QS?.get(`b20${key}`) ?? '').split(',').map(Number);
  return v.length === 3 && v.every(Number.isFinite) ? (v as [number, number, number]) : def;
}

/** shell-fur overrides (merged over the GLB's userData.fur and benny05's FUR05) */
export const FUR20: Record<string, Partial<FurParams>> = {
  fur_body: { shells: n('bsh', 24), length: n('blen', 0.075), gravity: n('bgr', 0.05) },
  fur_armL: { shells: n('ash', 16), length: n('alen', 0.07), gravity: n('agr', 0.1) },
  fur_armR: { shells: n('ash', 16), length: n('alen', 0.07), gravity: n('agr', 0.1) },
  fur_pom: { shells: n('psh', 20), length: n('plen', 0.12), gravity: n('pgr', 0.04) },
};

type V4 = [number, number, number, number];
/** lock shader parameters per part (fur.ts uLock / uShade / uComb) and flat albedo (LINEAR rgb). Albedos solved from a
 *  grey calibration sweep through the live 04 lighting + post chain (tools/benny20/calfit.py, qa/benny/r20/probe/c) for
 *  the approved means: fur (207, 74, 151), pompom (133, 30, 229) */
const LOCK20: Record<string, { lock: V4; shade: V4; comb: V4; pile: V4; color: [number, number, number] }> = {
  fur_body: {
    lock: [n('blx', 40), n('bly', 1.1), n('blz', 0.9), n('blw', 260)],
    shade: [n('bsx', 0.22), n('bsy', 0.3), n('bsz', 0.5), n('bsw', 0.3)],
    comb: [n('bcx', 0.6), n('bcy', 1.0), n('bcz', 0.1), n('bcw', 0.35)],
    pile: [n('bpx', 0.35), n('bpy', 0.45), n('bpz', 0.5), 0],
    color: lin('bcol', [0.29, 0.092, 0.172]),
  },
  fur_armL: {
    lock: [n('alx', 50), 0.95, n('alz', 0.9), 320],
    shade: [0.45, 0.25, 0.3, 0.3],
    comb: [n('acx', 0.4), 0.9, 0.08, 0.15],
    pile: [0.35, 0.5, 0.5, 0],
    color: lin('acol', [0.29, 0.092, 0.172]),
  },
  fur_armR: {
    lock: [n('alx', 50), 0.95, n('alz', 0.9), 320],
    shade: [0.45, 0.25, 0.3, 0.3],
    comb: [n('acx', 0.4), 0.9, 0.08, 0.15],
    pile: [0.35, 0.5, 0.5, 0],
    color: lin('acol', [0.29, 0.092, 0.172]),
  },
  fur_pom: {
    lock: [n('plx', 40), n('ply', 0.8), n('plz', 1.0), n('plw', 220)],
    shade: [n('psx', 0.45), n('psy', 0.3), n('psz', 0.35), n('psw', 0.3)],
    comb: [0, 1, n('pcz', 0.12), n('pcw', 0.3)],
    // w = lighter soft yarn tips: opt-in `&b20ppw=<0..1>` (r22 step 3) until proven
    pile: [n('ppx', 0.4), n('ppy', 0.35), n('ppz', 0.6), n('ppw', 0)],
    color: lin('pcol', [0.1016, 0.0067, 0.4425]),
  },
};

/** `&b20tuft=1` (r23 step 1, opt-in): soft FLUFFY plush volume instead of the flat velvet pile — medium-short soft
 *  tufts (bigger locks, a little longer fur, rounder tuft shading), lighter rose tips, soft highlight on the upper body /
 *  cheeks, deeper rose only in the underside creases. Every value overridable (`&b20t<key>=`). */
const TUFT = n('tuft', 0) > 0;
const VOL20: Record<string, V4> = {};
const TIP20: Record<string, [number, number, number]> = {};
if (TUFT) {
  const len = n('tlen', 0.08);
  for (const k of ['fur_body', 'fur_armL', 'fur_armR']) {
    const arm = k !== 'fur_body';
    FUR20[k].length = arm ? len * 0.8 : len;
    FUR20[k].gravity = n('tgr', 0.04);
    const L = LOCK20[k];
    L.lock = [n('tlx', arm ? 36 : 30), L.lock[1], L.lock[2], n('tlw', 180)];
    L.shade = [n('tsx', 0.62), n('tsy', 0.65), n('tsz', 0.35), n('tsw', 0.35)];
    L.comb = [n('tcx', 0.55), n('tcy', 1.0), L.comb[2], n('tcw', 0.5)];
    L.pile = [n('tpx', 0.4), n('tpy', 0.6), L.pile[2], n('tpw', 0.55)];
    VOL20[k] = [n('tvx', 0.35), n('tvy', 0.1), 0, 0];
    TIP20[k] = [n('ttr', 1.0), n('ttg', 0.42), n('ttb', 0.92)];
  }
}

/** per-screen fur exposure (LINEAR multipliers on the fur albedo above, which is solved for Screen 04). The approved
 *  pictures paint Benny lighter / pinker on 05–07 (fur mean ≈ (234, 82, 178), brightness median .95–.98) than on 04
 *  ((207, 74, 151), .84), while the game lights him less there. The game records its screen on
 *  benny.root.userData.stage (Game.ts setStage); runtime.ts eases the factor over ≈ 1 s. Unlisted screens: 04's look. */
export const EXPO20: Record<string, [number, number, number]> = {
  '05': lin('x05', [2.08, 1.54, 1.68]),
  '06': lin('x06', [1.73, 1.62, 1.5]),
  '07': lin('x07', [2.33, 1.59, 1.75]),
  '08': lin('x08', [2.0, 1.21, 1.7]),
};

const EXPO_ON = n('expo', 0) > 0;

/** beanie geometry on top of benny05's HAT05 (hat-local). Measured at the 04 start view against the approved silhouette
 *  (tools/benny20/score.py): cuff bottom on the centre column 1276 → 1271 px target, pompom 168 px wide like the approved */
export const HAT20 = {
  /** uniform scale of the whole beanie (cuff, crown, star, pompom) about the head centre */
  scale: n('hs', 1.1),
  /** extra drop along the body's up axis (units) */
  drop: n('hd', 0.02),
  /** backward tilt about the hat's X axis (rad, − = top toward his back): the BACK of the cuff (what the rear chase
   *  cameras see) comes down to the approved seat while the FRONT stays above his eyes (eye tops ≈ +0.18) */
  tilt: n('ht', -0.23),
  /** body-fur bald zone under the cuff: cos of the cone angle around the (tilted) hat up axis (GLB 0.414) */
  baldW: n('bw', 0.38),
  /** pompom: extra scale and lift (hat-local, after the beanie scale) */
  pomScale: n('ps', 1.03),
  pomDY: n('pdy', 0.0),
  /** star felt patch: thickness factor (GLB bevelled star ≈ 0.11 thick) */
  starFlat: n('sf', 0.3),
};

/** colour factors (LINEAR multipliers on the knit / felt maps, solved like the fur) + knit normal strength */
const MAT20 = {
  crown: lin('ccol', [0.78, 0.78, 0.7]),
  brim: lin('rcol', [0.67, 0.75, 0.57]),
  star: lin('scol', [0.34, 0.75, 1.0]),
  crownN: n('kcn', 2.0),
  brimN: n('kbn', 2.5),
};

const T = (f: string) => new URL(`../../../assets/textures/benny20/${f}`, import.meta.url).href;
const FILES = ['crown.png', 'crown_n.png', 'brim.png', 'brim_n.png', 'star.png', 'star_n.png'];
let loaded: Promise<Record<string, THREE.Texture | null>> | null = null;
/** load the knit / felt maps once (missing file → null: that part keeps its benny05 look) */
export function loadBenny20Maps(): Promise<Record<string, THREE.Texture | null>> {
  if (loaded) return loaded;
  const tl = new THREE.TextureLoader();
  loaded = Promise.all(
    FILES.map(async (f) => {
      try {
        const t = await tl.loadAsync(T(f));
        t.colorSpace = f.endsWith('_n.png') ? THREE.NoColorSpace : THREE.SRGBColorSpace;
        t.wrapS = f.startsWith('star') ? THREE.ClampToEdgeWrapping : THREE.RepeatWrapping;
        t.wrapT = THREE.ClampToEdgeWrapping;
        t.anisotropy = 4;
        t.needsUpdate = true;
        return [f, t] as const;
      } catch {
        console.warn('[benny20] missing map', f);
        return [f, null] as const;
      }
    }),
  ).then((e) => Object.fromEntries(e));
  return loaded;
}

/** per-frame: ease the fur albedo toward the current screen's exposure (EXPO20); returned by applyBenny20 */
export type Benny20Tick = (dt: number, stage: string | undefined) => void;

/** apply after applyBenny05 (same freshly cloned scene + fur handles) */
export function applyBenny20(scene: THREE.Object3D, furs: FurHandle[], maps: Record<string, THREE.Texture | null>): Benny20Tick {
  const get = (nm: string) => scene.getObjectByName(nm);
  const white = new THREE.DataTexture(new Uint8Array([255, 255, 255, 255]), 1, 1);
  white.needsUpdate = true;

  // ---- fur: plush locks, flat dusty-rose albedo ----
  for (const f of furs) {
    const spec = LOCK20[f.mesh.name];
    if (!spec) continue;
    const mat = f.material;
    const d = mat.defines ?? (mat.defines = {});
    d.BENNY20 = '';
    if (d.BENNY05 === undefined) d.BENNY05 = '';
    mat.map = white;
    mat.color.setRGB(...spec.color);
    f.uniforms.uRoot.value.setRGB(1, 1, 1);
    f.uniforms.uTip.value.setRGB(1, 1, 1);
    f.uniforms.uLock.value.set(...spec.lock);
    f.uniforms.uShade.value.set(...spec.shade);
    f.uniforms.uComb.value.set(...spec.comb);
    f.uniforms.uPile.value.set(...spec.pile);
    const vol = VOL20[f.mesh.name];
    if (vol) f.uniforms.uVol.value.set(...vol);
    const tc = TIP20[f.mesh.name];
    if (tc) f.uniforms.uTipCol.value.setRGB(...tc);
    mat.needsUpdate = true;
  }

  // ---- beanie: bigger, lower ----
  const hat = get('hat');
  if (hat) {
    hat.userData.b20rest = { y: hat.position.y, rx: hat.rotation.x, s: hat.scale.x };
    hat.scale.multiplyScalar(HAT20.scale);
    hat.position.y -= HAT20.drop;
    hat.rotation.x += HAT20.tilt;
    // body fur stays bald under the (now lower, tilted) cuff: cone axis follows the tilt (fur.ts uBald: xyz axis, w = cos)
    const body = furs.find((f) => f.mesh.name === 'fur_body');
    const ub = (body?.uniforms as unknown as { uBald?: { value: THREE.Vector4 } } | undefined)?.uBald;
    if (ub) {
      ub.value.w = HAT20.baldW;
      const ax = new THREE.Vector3(ub.value.x, ub.value.y, ub.value.z).applyAxisAngle(new THREE.Vector3(1, 0, 0), HAT20.tilt);
      ub.value.set(ax.x, ax.y, ax.z, HAT20.baldW);
    }
  }
  const pom = get('pom');
  if (pom) {
    pom.scale.multiplyScalar(HAT20.pomScale);
    pom.position.y += HAT20.pomDY;
  }

  // ---- knit maps on the crown / cuff ----
  const knit = (name: string, map: string, nmap: string, factor: [number, number, number], ns: number) => {
    const m = get(name) as THREE.Mesh | undefined;
    const tex = maps[map];
    if (!m || !tex) return;
    const mat = (m.material as THREE.MeshStandardMaterial).clone();
    mat.map = tex;
    mat.color.setRGB(...factor);
    const nt = maps[nmap];
    mat.normalMap = nt;
    if (nt) mat.normalScale.setScalar(ns);
    mat.roughness = 0.92;
    mat.metalness = 0;
    mat.needsUpdate = true;
    m.material = mat;
  };
  // procedural knit maps: opt-in `&b20knit=1` until they beat benny05's approved-pixel beanie maps (kept by default)
  if (n('knit', 0) > 0) {
    knit('hat_crown', 'crown.png', 'crown_n.png', MAT20.crown, MAT20.crownN);
    knit('hat_brim', 'brim.png', 'brim_n.png', MAT20.brim, MAT20.brimN);
  }

  // ---- star: flat stitched felt patch ----
  const star = get('hat_star') as THREE.Mesh | undefined;
  if (star && maps['star.png']) {
    star.scale.z *= HAT20.starFlat;
    const mat = (star.material as THREE.MeshStandardMaterial).clone();
    mat.map = maps['star.png'];
    mat.normalMap = maps['star_n.png'];
    mat.normalScale.setScalar(1);
    mat.color.setRGB(...MAT20.star);
    mat.roughness = 0.97;
    mat.metalness = 0;
    mat.emissive.setRGB(1, 0.72, 0.2);
    mat.emissiveIntensity = n('se', 0.08);
    mat.needsUpdate = true;
    star.material = mat;
  }

  // ---- per-screen fur exposure (body + arms) ----
  const expo = furs.filter((f) => /^fur_(body|arm)/.test(f.mesh.name)).map((f) => ({ f, base: f.material.color.clone() }));
  const cur = new THREE.Vector3(1, 1, 1);
  const tgt = new THREE.Vector3();
  let first = true;
  const lastPos = new THREE.Vector3();
  const pos = new THREE.Vector3();
  const tick: Benny20Tick = (dt, stage) => {
    // opt-in `&b20expo=1` until proven in motion on 05–07 (step-1 pictures were made without it)
    const e = (EXPO_ON && stage && EXPO20[stage]) || [1, 1, 1];
    tgt.set(e[0], e[1], e[2]);
    // ease while riding from one screen into the next; snap on the first frame and after a jump (checkpoint / QA goto)
    scene.getWorldPosition(pos);
    const jumped = pos.distanceTo(lastPos) > 5;
    lastPos.copy(pos);
    if (first || jumped) { cur.copy(tgt); first = false; } else cur.lerp(tgt, 1 - Math.exp(-dt * 3));
    for (const { f, base } of expo) f.material.color.setRGB(base.r * cur.x, base.g * cur.y, base.b * cur.z);
  };

  // QA only (`?qa` pages, read by tools/benny20/probe.mjs): live handles for tuning without a reload
  if (QS?.has('qa') && typeof window !== 'undefined') {
    /** QA (tools/benny23/shots_c.mjs): Benny's screen box in pixels for the live camera returned by __rainbow.camera() */
    const screenBox = (c: { matrixWorld: number[]; fov: number; aspect: number; near: number; far: number; width: number; height: number }) => {
      const cam = new THREE.PerspectiveCamera(c.fov, c.aspect, c.near, c.far);
      cam.matrixWorld.fromArray(c.matrixWorld);
      cam.matrixWorldInverse.copy(cam.matrixWorld).invert();
      const bb = new THREE.Box3().setFromObject(scene);
      let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
      for (let i = 0; i < 8; i++) {
        const v = new THREE.Vector3(i & 1 ? bb.max.x : bb.min.x, i & 2 ? bb.max.y : bb.min.y, i & 4 ? bb.max.z : bb.min.z).project(cam);
        const px = (v.x * 0.5 + 0.5) * c.width, py = (0.5 - v.y * 0.5) * c.height;
        x0 = Math.min(x0, px); y0 = Math.min(y0, py); x1 = Math.max(x1, px); y1 = Math.max(y1, py);
      }
      return [Math.round(x0), Math.round(y0), Math.round(x1), Math.round(y1)];
    };
    (window as unknown as { __b20?: unknown }).__b20 = { scene, furs, hat, pom, star, HAT20, LOCK20, EXPO20, expo, screenBox };
  }
  return tick;
}

// benny-character-artist r20 (read-only QA): load the game ONCE, go to a screen checkpoint, then render many look variants
// of Benny at the same frozen frame (no sim step between variants: only the renderer runs) → <outDir>/<name>.png
// (+ <name>_mask.png with B20_MASK=1: flat part colours on white, fur red / pom green / crown cyan / cuff blue / star black).
//   node tools/benny20/probe.mjs <outDir> "<query>" <variants.json> [screen=04] [dist=0]
// variants.json: [{ "name": "v1", "js": "B.hat.scale.multiplyScalar(1.05)" }, ...] — js runs in the page with
// B = window.__b20 (benny20.ts QA handle), R = window.__rainbow; each variant starts from the previous variant's state.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { loadPlaywright, CHROMIUM_ARGS, startVite } from '../../scripts/lib/pw.mjs';
const [OUT, Q = '', VJ, SCR = '04', DIST = '0'] = process.argv.slice(2);
mkdirSync(OUT, { recursive: true });
const variants = JSON.parse(readFileSync(VJ, 'utf8'));
const { chromium } = loadPlaywright();
const vite = await startVite(Number(process.env.B20_PORT ?? 5278));
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  page.on('pageerror', (e) => console.error('pageerror', e.message));
  page.on('console', (m) => { if (m.type() === 'error' && !/Failed to load resource/.test(m.text())) console.error('console', m.text().slice(0, 300)); });
  await page.goto(`${vite.url}/?qa=1&dpr=1${Q ? '&' + Q : ''}`);
